      "rank": 8,
      "ballot_id": "B001",
      "proposed_laureates": ["Frans Pretorius", "John G. Baker", "Manuela Campanelli"],
      "assessment": {
        "nobel_worthiness": "Stable numerical solutions for binary black-hole mergers made a central prediction of general relativity computationally tractable and enabled gravitational-wave astronomy.",
        "attribution": "Pretorius, Baker, and Campanelli made landmark contributions to the successful numerical-relativity breakthroughs.",
        "maturity": "The methods have been tested against observed gravitational-wave signals and underpin a mature field.",
        "uncertainties": ["The decisive advances were achieved by multiple groups in close succession, so priority and the boundaries of credit require careful assessment."]
      }
    }
  ]
